class Solution:

	def findShortestPath(self, mat: List[List[int]]) -> int:
		(n, m) = (len(mat), len(mat[0]))
		dr = [(-1, 0), (0, 1), (1, 0), (0, -1)]

		def outBounds(i, j):
			if i <= -1 or i >= n or j <= -1 or (j >= m):
				return True
			return False

		def isSafe(i, j):
			if outBounds(i, j) or mat[i][j] == 0:
				return False
			for d in dr:
				(x, y) = (i + d[0], j + d[1])
				if not outBounds(x, y) and mat[x][y] == 0:
					return False
			return True

		def rec(i, j):
			if memo[i][j] != -1 and memo[i][j] != float('inf'):
				return memo[i][j]
			if j == m - 1:
				return 1
			visited.add((i, j))
			min_ = float('inf')
			for d in dr:
				if d == (0, -1):
					continue
				(x, y) = (i + d[0], j + d[1])
				if (x, y) not in visited and isSafe(x, y):
					min_ = min(min_, 1 + rec(x, y))
			memo[i][j] = min_
			visited.remove((i, j))
			return memo[i][j]
		visited = set()
		memo = [[-1 for j in range(m)] for i in range(n)]
		min_ = float('inf')
		for i in range(n):
			if isSafe(i, 0):
				min_ = min(min_, rec(i, 0))
		return -1 if min_ == float('inf') else min_

