class Solution:

	def find(self, root, target):
		node = root
		while node:
			if node.data == target:
				return node
			elif target < node.data:
				node = node.left
			else:
				node = node.right
		return node

	def get_sum_of_descendants(self, root):
		q = deque()
		q.append((root, 0))
		desc_sum = 0
		while q:
			(node, rank) = q.popleft()
			if node is None:
				continue
			if rank == 0:
				desc_sum += node.data
			q.extend([(node.left, rank - 1), (node.right, rank + 1)])
		return desc_sum - root.data

	def verticallyDownBST(self, root, target):
		node = self.find(root, target)
		if node is None:
			return -1
		desc_sum = self.get_sum_of_descendants(node)
		return desc_sum

